package kr.minecraft.survival.codex;

import java.nio.file.*;
import java.util.*;
import org.bukkit.*;
import org.bukkit.attribute.*;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.*;
import org.bukkit.inventory.*;
import org.bukkit.inventory.meta.ItemMeta;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.mockbukkit.mockbukkit.*;
import org.mockbukkit.mockbukkit.entity.PlayerMock;
import kr.minecraft.survival.menu.KoreanMenuPlugin;

class CodexTest {
    ServerMock server;KoreanCodexPlugin plugin;SavedPlayer p;
    /** MockBukkit has no player.dat persistence. Count/inject save failures, while using real SQLite. */
    static class SavedPlayer extends PlayerMock {
        int saves,failOn;private AttributeInstance mining;
        SavedPlayer(ServerMock server,String name){super(server,name);}
        @Override public void saveData(){saves++;if(saves==failOn)throw new IllegalStateException("injected player save failure");}
        // MockBukkit's global default map omits BLOCK_BREAK_SPEED. Use its real attribute instance with vanilla base 1.
        @Override public AttributeInstance getAttribute(Attribute attribute){if(attribute==Attribute.BLOCK_BREAK_SPEED){if(mining==null)mining=new org.mockbukkit.mockbukkit.attribute.AttributeInstanceMock(attribute,1.0);return mining;}return super.getAttribute(attribute);}
    }
    @BeforeEach void start(){server=MockBukkit.mock();server.addSimpleWorld("world");plugin=MockBukkit.load(KoreanCodexPlugin.class);assertTrue(plugin.isEnabled());p=new SavedPlayer(server,"Collector");server.addPlayer(p);p.setGameMode(GameMode.SURVIVAL);}
    @AfterEach void stop(){MockBukkit.unmock();}
    Catalog.Entry entry(String id){return plugin.catalog.entry(id);}
    void give(String id,int amount){p.getInventory().setItem(0,new ItemStack(Material.valueOf(entry(id).material()),amount));}
    void register(String id){give(id,2);plugin.registerItem(p,entry(id));}
    void click(int slot){var e=new InventoryClickEvent(p.getOpenInventory(),InventoryType.SlotType.CONTAINER,slot,ClickType.LEFT,InventoryAction.PICKUP_ALL);server.getPluginManager().callEvent(e);assertTrue(e.isCancelled());server.getScheduler().performTicks(3);}
    @Test void eightyFiveEntriesThirteenAwardsAndCustomProviderIsOptional(){assertEquals(85,plugin.catalog.entries.size());assertEquals(9,plugin.catalog.categories.size());assertEquals(13,plugin.catalog.achievements.size());Set<String> materials=new HashSet<>();for(var e:plugin.catalog.entries.values()){assertNotEquals(Material.AIR,Material.valueOf(e.material()));if(e.customId().isEmpty())assertTrue(materials.add(e.material()));}assertFalse(materials.contains("DRAGON_EGG"));}
    @Test void rareItemsGiveExactDifficultyMultiplesWithinSameCategory(){for(var c:plugin.catalog.categories){int unit=plugin.catalog.entryUnits(c.entries().getFirst())/c.entries().getFirst().weight();assertTrue(unit>0);for(var e:c.entries())assertEquals(unit*e.weight(),plugin.catalog.entryUnits(e));}}
    @Test void fullCollectionExactlyReachesAllEightSmallCaps(){var values=plugin.catalog.bonuses(plugin.catalog.entries.keySet());for(var stat:Catalog.Stat.values())assertEquals(stat.cap,values.get(stat));assertEquals(13,plugin.catalog.eligible(plugin.catalog.entries.keySet()).size());}
    @Test void everyPartialCollectionIsMonotonicAndBounded(){Set<String> done=new HashSet<>();Map<Catalog.Stat,Integer> previous=plugin.catalog.bonuses(done);for(var e:plugin.catalog.entries.values()){done.add(e.id());var current=plugin.catalog.bonuses(done);for(var stat:Catalog.Stat.values()){assertTrue(current.get(stat)>=previous.get(stat));assertTrue(current.get(stat)<=stat.cap);}previous=current;}}
    @Test void confirmationConsumesExactlyOneAndSavesPermanentRegistration(){give("oak_log",3);plugin.confirmation(p,entry("oak_log"));assertEquals(3,p.getInventory().getItem(0).getAmount());click(30);assertEquals(2,p.getInventory().getItem(0).getAmount());assertTrue(plugin.store.registered(p.getUniqueId()).contains("oak_log"));assertEquals(3,p.saves);}
    @Test void cancellingDoesNotConsumeOrRegister(){give("diamond",2);plugin.confirmation(p,entry("diamond"));click(32);assertEquals(2,p.getInventory().getItem(0).getAmount());assertTrue(plugin.store.registered(p.getUniqueId()).isEmpty());}
    @Test void duplicateRegistrationCannotConsumeAgainOrStackBonus(){register("oak_log");double value=p.getAttribute(Attribute.MOVEMENT_SPEED).getValue();assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("oak_log")));assertEquals(1,p.getInventory().getItem(0).getAmount());assertEquals(value,p.getAttribute(Attribute.MOVEMENT_SPEED).getValue());}
    @Test void namedEnchantedDamagedAndCustomModelItemsAreNotConsumed(){for(String id:List.of("diamond","elytra")){give(id,1);ItemStack item=p.getInventory().getItem(0);ItemMeta meta=item.getItemMeta();meta.setDisplayName("기념품");item.setItemMeta(meta);p.getInventory().setItem(0,item);assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry(id)));assertEquals(1,p.getInventory().getItem(0).getAmount());}give("elytra",1);ItemStack wings=p.getInventory().getItem(0);var damaged=(org.bukkit.inventory.meta.Damageable)wings.getItemMeta();damaged.setDamage(1);wings.setItemMeta(damaged);p.getInventory().setItem(0,wings);assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("elytra")));give("diamond",1);ItemStack special=p.getInventory().getItem(0);var meta=special.getItemMeta();meta.setItemModel(new NamespacedKey("other","gem"));special.setItemMeta(meta);p.getInventory().setItem(0,special);assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));}
    @Test void offhandAndEquipmentAreExcluded(){p.getInventory().setItemInOffHand(new ItemStack(Material.DIAMOND));assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));assertEquals(1,p.getInventory().getItemInOffHand().getAmount());}
    @Test void creativeOrSpectatorCannotRegister(){give("diamond",2);for(GameMode mode:List.of(GameMode.CREATIVE,GameMode.SPECTATOR)){p.setGameMode(mode);assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));}assertEquals(2,p.getInventory().getItem(0).getAmount());}
    @Test void healthBonusDoesNotHealAndTogglingCannotHeal(){double start=p.getHealth();register("wheat");AttributeInstance hp=p.getAttribute(Attribute.MAX_HEALTH);assertTrue(hp.getValue()>20);assertEquals(start,p.getHealth());server.dispatchCommand(p,"도감효과 끄기");assertEquals(20,hp.getValue());server.dispatchCommand(p,"도감효과 켜기");assertTrue(hp.getValue()>20);assertEquals(start,p.getHealth());}
    @Test void loweringMaximumHealthClampsCurrentHealthWithoutDeletingOtherModifiers(){register("wheat");AttributeInstance hp=p.getAttribute(Attribute.MAX_HEALTH);var other=new AttributeModifier(new NamespacedKey("other","health"),1,AttributeModifier.Operation.ADD_NUMBER);hp.addModifier(other);p.setHealth(hp.getValue());server.dispatchCommand(p,"도감효과 끄기");assertNotNull(hp.getModifier(new NamespacedKey("other","health")));assertEquals(21,hp.getValue());assertEquals(21,p.getHealth());}
    @Test void synchronizationAndReconnectDoNotStackOrChangeBaseValues(){double base=p.getAttribute(Attribute.MOVEMENT_SPEED).getBaseValue();register("oak_log");double once=p.getAttribute(Attribute.MOVEMENT_SPEED).getValue();for(int i=0;i<20;i++)plugin.apply(p);assertEquals(once,p.getAttribute(Attribute.MOVEMENT_SPEED).getValue());plugin.load(p);plugin.load(p);assertEquals(once,p.getAttribute(Attribute.MOVEMENT_SPEED).getValue());assertEquals(base,p.getAttribute(Attribute.MOVEMENT_SPEED).getBaseValue());}
    @Test void otherSpeedModifiersRemainAndOnlyOurTransientKeysAreRemoved(){var speed=p.getAttribute(Attribute.MOVEMENT_SPEED);var external=new AttributeModifier(new NamespacedKey("other","speed"),0.1,AttributeModifier.Operation.ADD_SCALAR);speed.addModifier(external);register("oak_log");plugin.bonuses.remove(p);assertNotNull(speed.getModifier(new NamespacedKey("other","speed")));assertNull(speed.getModifier(plugin.bonuses.keys.get(Catalog.Stat.MOVE)));}
    @Test void allEightAttributesExistAndAreAppliedAtFullCollection(){var values=plugin.catalog.bonuses(plugin.catalog.entries.keySet());plugin.bonuses.apply(p,values,true);for(var stat:Catalog.Stat.values()){var instance=p.getAttribute(Bonuses.attribute(stat));assertNotNull(instance,"missing attribute "+stat);var mod=instance.getModifier(plugin.bonuses.keys.get(stat));assertNotNull(mod,"missing modifier "+stat);assertEquals(stat.cap/10000.0,mod.getAmount());assertEquals(Bonuses.operation(stat),mod.getOperation());}}
    @Test void saveFailureBeforeConsumptionLeavesReviewAndBlocksAnotherAttempt(){give("diamond",2);p.failOn=1;assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));assertEquals(2,p.getInventory().getItem(0).getAmount());assertEquals(1,plugin.store.unresolved().size());assertTrue(plugin.store.registered(p.getUniqueId()).isEmpty());p.failOn=0;assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));assertEquals(2,p.getInventory().getItem(0).getAmount());}
    @Test void saveFailureAfterConsumptionDoesNotConsumeTwice(){give("diamond",3);p.failOn=2;assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));assertEquals(2,p.getInventory().getItem(0).getAmount());assertTrue(plugin.store.registered(p.getUniqueId()).isEmpty());p.failOn=0;assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));assertEquals(2,p.getInventory().getItem(0).getAmount());}
    @Test void cleanupFailureAfterCommitDoesNotUndoSuccessfulRegistration(){give("diamond",2);p.failOn=3;plugin.registerItem(p,entry("diamond"));assertTrue(plugin.store.registered(p.getUniqueId()).contains("diamond"));assertEquals(1,p.getInventory().getItem(0).getAmount());assertTrue(plugin.store.unresolved().isEmpty());}
    @Test void doubleClickOnConfirmCanOnlyRegisterOnce(){give("diamond",3);plugin.confirmation(p,entry("diamond"));var view=p.getOpenInventory();for(int i=0;i<2;i++){var event=new InventoryClickEvent(view,InventoryType.SlotType.CONTAINER,30,ClickType.LEFT,InventoryAction.PICKUP_ALL);server.getPluginManager().callEvent(event);assertTrue(event.isCancelled());}server.getScheduler().performTicks(3);assertEquals(2,p.getInventory().getItem(0).getAmount());assertTrue(plugin.store.registered(p.getUniqueId()).contains("diamond"));}
    @Test void menusBlockNumberKeysShiftClickAndDragging(){plugin.home(p);for(ClickType type:List.of(ClickType.SHIFT_LEFT,ClickType.DOUBLE_CLICK)){var e=new InventoryClickEvent(p.getOpenInventory(),InventoryType.SlotType.CONTAINER,10,type,InventoryAction.MOVE_TO_OTHER_INVENTORY);server.getPluginManager().callEvent(e);assertTrue(e.isCancelled());}var hotbar=new InventoryClickEvent(p.getOpenInventory(),InventoryType.SlotType.CONTAINER,10,ClickType.NUMBER_KEY,InventoryAction.HOTBAR_SWAP,0);server.getPluginManager().callEvent(hotbar);assertTrue(hotbar.isCancelled());var drag=new InventoryDragEvent(p.getOpenInventory(),new ItemStack(Material.AIR),new ItemStack(Material.PAPER),false,Map.of(10,new ItemStack(Material.PAPER)));server.getPluginManager().callEvent(drag);assertTrue(drag.isCancelled());assertTrue(p.getInventory().isEmpty());}
    @Test void actualKoreanMenuGetsButtonsInBlankSlotsAndRestoresOnClose(){var menu=MockBukkit.loadWith(KoreanMenuPlugin.class,Path.of(System.getProperty("codex.repo"),"korean-menu/src/main/resources/plugin.yml").toFile());server.getPluginManager().addPermissions(menu.getDescription().getPermissions());p.recalculatePermissions();server.dispatchCommand(p,"메뉴");server.getScheduler().performTicks(3);Inventory original=p.getOpenInventory().getTopInventory();assertEquals(Material.BOOK,original.getItem(20).getType());assertEquals(Material.GOLDEN_CHESTPLATE,original.getItem(26).getType());click(20);assertTrue(p.getOpenInventory().getTopInventory().getHolder() instanceof KoreanCodexPlugin.Screen);assertEquals(Material.GRAY_STAINED_GLASS_PANE,original.getItem(20).getType());assertFalse(p.isOp());assertTrue(menu.isEnabled());}
    @Test void achievementsAreGrantedOnceWithTenCollectionRegistrations(){for(var e:plugin.catalog.categories.getFirst().entries())register(e.id());assertEquals(Set.of("total_10","category_forest"),plugin.store.awards(p.getUniqueId()));plugin.load(p);assertEquals(2,plugin.store.awards(p.getUniqueId()).size());}
    @Test void restartPreservesDoneRecordsPreferencesAndQuarantinesPending()throws Exception {Path dir=Files.createTempDirectory("codex-restart-");UUID id=UUID.randomUUID();String pending;
        try(var store=new CodexStore(dir.resolve("codex.db"))){store.player(id,"Saved");var r=store.reserve(id,"oak_log",0,2,"before","after");store.finish(r.id(),plugin.catalog,false);store.enabled(id,false);pending=store.reserve(id,"diamond",0,2,"b","a").id();}
        try(var store=new CodexStore(dir.resolve("codex.db"))){assertEquals(Set.of("oak_log"),store.registered(id));assertFalse(store.enabled(id));assertEquals("REVIEW",store.receipt(pending).state());assertThrows(CodexStore.Denied.class,()->store.reserve(id,"wheat",0,1,"b","a"));store.finish(pending,plugin.catalog,true);assertEquals(Set.of("oak_log","diamond"),store.registered(id));assertThrows(CodexStore.Denied.class,()->store.finish(pending,plugin.catalog,true));}
    }
    @Test void cancelledReviewAllowsRetryWithoutGrantingAnyCollection(){UUID id=p.getUniqueId();var r=plugin.store.reserve(id,"diamond",0,2,"b","a");plugin.store.review(r.id(),"test");plugin.store.cancel(r.id(),"admin confirmed item not consumed");assertTrue(plugin.store.registered(id).isEmpty());assertNotNull(plugin.store.reserve(id,"diamond",0,2,"b","a"));}
    @Test void databaseSnapshotContainsRegistrationsAndNoReplay()throws Exception {register("oak_log");Path snapshot=Files.createTempDirectory("codex-snapshot-").resolve("copy.db");plugin.store.snapshot(snapshot);try(var copy=new CodexStore(snapshot)){assertEquals(Set.of("oak_log"),copy.registered(p.getUniqueId()));}}
    @Test void permissionsAndCreativeModeRemoveOnlyOurBonusOnSync(){register("oak_log");p.addAttachment(plugin,"koreancodex.use",false);plugin.apply(p);assertNull(p.getAttribute(Attribute.MOVEMENT_SPEED).getModifier(plugin.bonuses.keys.get(Catalog.Stat.MOVE)));p.addAttachment(plugin,"koreancodex.use",true);p.setGameMode(GameMode.CREATIVE);plugin.apply(p);assertNull(p.getAttribute(Attribute.MOVEMENT_SPEED).getModifier(plugin.bonuses.keys.get(Catalog.Stat.MOVE)));}
    @Test void everyCategoryHasAnActualCommonBaselineAndScarceItemsAreEightTimesIt(){
        for(var c:plugin.catalog.categories){var common=c.entries().stream().filter(e->e.weight()==1).findFirst().orElseThrow();for(var e:c.entries())assertEquals(plugin.catalog.entryUnits(common)*e.weight(),plugin.catalog.entryUnits(e));}
        for(String id:List.of("nether_star","elytra","netherite_ingot"))assertEquals(8,entry(id).weight());
        assertEquals("+2%p",Catalog.Stat.KNOCKBACK.format(200));
    }
    @Test void enchantmentAndPersistentDataAreNotPlainItems(){
        give("elytra",1);ItemStack item=p.getInventory().getItem(0);var meta=item.getItemMeta();meta.addEnchant(org.bukkit.enchantments.Enchantment.UNBREAKING,1,false);item.setItemMeta(meta);p.getInventory().setItem(0,item);assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("elytra")));assertEquals(item,p.getInventory().getItem(0));
        give("diamond",2);item=p.getInventory().getItem(0);meta=item.getItemMeta();meta.getPersistentDataContainer().set(new NamespacedKey("other","custom"),org.bukkit.persistence.PersistentDataType.INTEGER,1);item.setItemMeta(meta);p.getInventory().setItem(0,item);assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));assertEquals(item,p.getInventory().getItem(0));
    }
    @Test void databaseFailureAfterConsumptionLeavesReviewAndCannotConsumeAgain(){
        give("diamond",3);plugin.store.execute("CREATE TRIGGER fail_finish BEFORE UPDATE ON registrations WHEN NEW.state='DONE' BEGIN SELECT RAISE(ABORT,'injected commit failure'); END");
        assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));assertEquals(2,p.getInventory().getItem(0).getAmount());assertEquals(1,plugin.store.unresolved().size());assertTrue(plugin.store.registered(p.getUniqueId()).isEmpty());assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));assertEquals(2,p.getInventory().getItem(0).getAmount());
    }
    @Test void missingReceiptMarkerIsPersistentlyQuarantinedAndOnlyAdminCanRelease(){
        give("diamond",2);String marker=UUID.randomUUID()+":CONSUMED";p.getPersistentDataContainer().set(plugin.pendingKey,org.bukkit.persistence.PersistentDataType.STRING,marker);plugin.load(p);assertTrue(plugin.store.markerHeld(p.getUniqueId()));assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("diamond")));assertEquals(2,p.getInventory().getItem(0).getAmount());
        server.dispatchCommand(p,"도감관리 표식해제 Collector 확인");assertTrue(plugin.store.markerHeld(p.getUniqueId()));p.setOp(true);server.dispatchCommand(p,"도감관리 표식해제 Collector 확인");assertFalse(plugin.store.markerHeld(p.getUniqueId()));assertNull(p.getPersistentDataContainer().get(plugin.pendingKey,org.bukkit.persistence.PersistentDataType.STRING));assertEquals(2,p.getInventory().getItem(0).getAmount());assertTrue(plugin.store.registered(p.getUniqueId()).isEmpty());
    }
    @Test void markerQuarantineAndOperatorAcknowledgementSurviveRestart()throws Exception{
        Path path=Files.createTempDirectory("codex-marker-").resolve("codex.db");UUID id=UUID.randomUUID();String marker=UUID.randomUUID()+":BEFORE";
        try(var db=new CodexStore(path)){db.player(id,"Lost");db.markerReview(id,marker);}
        try(var db=new CodexStore(path)){assertTrue(db.markerHeld(id));assertThrows(CodexStore.Denied.class,()->db.reserve(id,"diamond",0,2,"b","a"));db.releaseMarkers(id,"Operator");}
        try(var db=new CodexStore(path)){db.markerReview(id,marker);assertFalse(db.markerHeld(id));assertTrue(db.markerReleased(id,marker));assertTrue(db.registered(id).isEmpty());}
    }
    @Test void v1DatabaseMigrationKeepsCollectionPreferenceAndAwards()throws Exception{
        Path path=Files.createTempDirectory("codex-v1-").resolve("codex.db");UUID id=UUID.randomUUID();
        try(var db=new CodexStore(path)){db.player(id,"Existing");for(var e:plugin.catalog.categories.getFirst().entries())db.finish(db.reserve(id,e.id(),0,2,"b","a").id(),plugin.catalog,false);db.enabled(id,false);db.execute("DROP TABLE marker_reviews");db.execute("PRAGMA user_version=1");}
        try(var db=new CodexStore(path)){assertEquals(10,db.registered(id).size());assertEquals(2,db.awards(id).size());assertFalse(db.enabled(id));assertFalse(db.markerHeld(id));}
    }
    @Test void injuredPlayerCannotHealByGainingOrTogglingHealthBonus(){p.setHealth(11);register("wheat");assertEquals(11,p.getHealth());for(int i=0;i<3;i++){server.dispatchCommand(p,"도감효과 끄기");server.dispatchCommand(p,"도감효과 켜기");}assertEquals(11,p.getHealth());}
    @Test void originalEightyStillReachTheSameCapsWithoutFarmRegistration(){Set<String> old=new HashSet<>();for(var e:plugin.catalog.entries.values())if(e.customId().isEmpty())old.add(e.id());assertEquals(80,old.size());assertEquals(12,plugin.catalog.eligible(old).size());for(var stat:Catalog.Stat.values())assertEquals(stat.cap,plugin.catalog.bonuses(old).get(stat));}
    @Test void farmCollectionAddsOnlyTinyHealthAndCompletionSpeedWithinExistingCaps(){Set<String> crops=Set.of("farm_strawberry","farm_tomato","farm_corn","farm_rice","farm_cucumber");var values=plugin.catalog.bonuses(crops);assertEquals(1000,values.get(Catalog.Stat.HEALTH));assertEquals(10,values.get(Catalog.Stat.MOVE));for(var stat:Catalog.Stat.values())assertTrue(values.get(stat)<=stat.cap);assertEquals(Set.of("category_custom_farm"),plugin.catalog.eligible(crops));}
    @Test void unavailableFarmCannotConsumeVanillaFoodAsCustomCrop(){p.getInventory().setItem(0,new ItemStack(Material.APPLE,2));assertFalse(plugin.matches(p.getInventory().getItem(0),entry("farm_strawberry")));assertThrows(CodexStore.Denied.class,()->plugin.registerItem(p,entry("farm_strawberry")));assertEquals(2,p.getInventory().getItem(0).getAmount());}

}
